/**
 * p5.js Lightweight Engine Distribution for Embedded Android Runtime
 * Supports p5 Instance Mode: new p5(sketchFunction, containerElement)
 */
(function (global) {
  'use strict';

  // Vector Utility Class
  class Vector {
    constructor(x = 0, y = 0, z = 0) {
      this.x = x;
      this.y = y;
      this.z = z;
    }
    set(x, y, z) {
      this.x = x || 0;
      this.y = y || 0;
      this.z = z || 0;
      return this;
    }
    add(v) {
      if (v instanceof Vector) { this.x += v.x; this.y += v.y; this.z += v.z; }
      else { this.x += arguments[0] || 0; this.y += arguments[1] || 0; }
      return this;
    }
    sub(v) {
      if (v instanceof Vector) { this.x -= v.x; this.y -= v.y; this.z -= v.z; }
      else { this.x -= arguments[0] || 0; this.y -= arguments[1] || 0; }
      return this;
    }
    mult(n) { this.x *= n; this.y *= n; this.z *= n; return this; }
    div(n) { if (n !== 0) { this.x /= n; this.y /= n; this.z /= n; } return this; }
    mag() { return Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z); }
    heading() { return Math.atan2(this.y, this.x); }
    normalize() { const m = this.mag(); if (m > 0) this.div(m); return this; }
    limit(max) { if (this.mag() > max) { this.normalize(); this.mult(max); } return this; }
    copy() { return new Vector(this.x, this.y, this.z); }
    static dist(v1, v2) { return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2); }
    static random2D() {
      const angle = Math.random() * Math.PI * 2;
      return new Vector(Math.cos(angle), Math.sin(angle));
    }
  }

  // Simplex/Perlin Noise Utility
  function createNoise() {
    const p = new Uint8Array(256);
    for (let i = 0; i < 256; i++) p[i] = Math.floor(Math.random() * 256);
    const perm = new Uint8Array(512);
    for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
    return function (x, y = 0) {
      const X = Math.floor(x) & 255, Y = Math.floor(y) & 255;
      x -= Math.floor(x); y -= Math.floor(y);
      const u = x * x * x * (x * (x * 6 - 15) + 10);
      const v = y * y * y * (y * (y * 6 - 15) + 10);
      const A = perm[X] + Y, B = perm[X + 1] + Y;
      return (perm[A] + perm[B]) / 512 + u * 0.1 + v * 0.1;
    };
  }

  // HSB (h: 0-360, s/b: 0-100) to RGB triple
  function hsbToRgb(h, s, v) {
    s /= 100; v /= 100;
    const c = v * s;
    const hp = (((h % 360) + 360) % 360) / 60;
    const x = c * (1 - Math.abs(hp % 2 - 1));
    let r = 0, g = 0, b = 0;
    if (hp < 1) { r = c; g = x; } else if (hp < 2) { r = x; g = c; }
    else if (hp < 3) { g = c; b = x; } else if (hp < 4) { g = x; b = c; }
    else if (hp < 5) { r = x; b = c; } else { r = c; b = x; }
    const m = v - c;
    return [Math.round((r + m) * 255), Math.round((g + m) * 255), Math.round((b + m) * 255)];
  }

  function p5(sketchFunc, node) {
    if (!(this instanceof p5)) return new p5(sketchFunc, node);

    this._container = typeof node === 'string' ? document.getElementById(node) : node;
    this.width = this._container ? this._container.clientWidth || window.innerWidth : window.innerWidth;
    this.height = this._container ? this._container.clientHeight || window.innerHeight : window.innerHeight;

    this.canvas = null;
    this.ctx = null;
    this.isLooping = true;
    this.frameCount = 0;
    this.frameRate = 60;
    this._fps = 60;
    this._lastFrameTime = performance.now();

    // Mouse & Touch States
    this.mouseX = 0;
    this.mouseY = 0;
    this.pmouseX = 0;
    this.pmouseY = 0;
    this.touchX = 0;
    this.touchY = 0;
    this.touches = [];
    this.mouseIsPressed = false;

    // Constants
    this.WEBGL = 'WEBGL';
    this.P2D = 'P2D';
    this.RGB = 'RGB';
    this.HSB = 'HSB';
    this.CENTER = 'center';
    this.CORNER = 'corner';
    this._colorMode = 'RGB';

    // State styling
    this._fill = 'rgba(255, 255, 255, 1)';
    this._stroke = 'rgba(0, 0, 0, 1)';
    this._doFill = true;
    this._doStroke = true;
    this._strokeWeight = 1;
    this._rectMode = this.CORNER;
    this.Vector = Vector;

    // Resolves p5-style color args to a CSS color string.
    // - 3-4 numeric args in HSB mode convert hue/saturation/brightness to RGB
    // - 2 numeric args are (gray, alpha) like real p5
    // - alpha above 1 is assumed to be on the 255 scale and normalized
    this.resolveColor = (r, g, b, a) => {
      if (typeof r !== 'number') return r || '#000000';
      const alpha = a === undefined ? undefined : (a > 1 ? a / 255 : a);
      if (this._colorMode === this.HSB && b !== undefined) {
        const [rr, gg, bb] = hsbToRgb(r, g, b);
        return alpha === undefined ? `rgb(${rr},${gg},${bb})` : `rgba(${rr},${gg},${bb},${alpha})`;
      }
      if (g === undefined) return `rgb(${r},${r},${r})`;
      if (b === undefined) return `rgba(${r},${r},${r},${g > 1 ? g / 255 : g})`;
      return alpha === undefined ? `rgb(${r},${g},${b})` : `rgba(${r},${g},${b},${alpha})`;
    };

    // Bind instance methods to this p5 instance
    this.createVector = (x, y, z) => new Vector(x, y, z);
    this.random = (a, b) => {
      if (Array.isArray(a)) return a[Math.floor(Math.random() * a.length)];
      if (a !== undefined && b !== undefined) return a + Math.random() * (b - a);
      if (a !== undefined) return Math.random() * a;
      return Math.random();
    };
    this.noise = createNoise();
    this.map = (n, start1, stop1, start2, stop2) => ((n - start1) / (stop1 - start1)) * (stop2 - start2) + start2;
    this.dist = (x1, y1, x2, y2) => Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
    this.lerp = (a, b, t) => a + (b - a) * t;
    this.sin = Math.sin;
    this.cos = Math.cos;
    this.tan = Math.tan;
    this.atan2 = Math.atan2;
    this.floor = Math.floor;
    this.ceil = Math.ceil;
    this.abs = Math.abs;
    this.min = Math.min;
    this.max = Math.max;
    this.pow = Math.pow;
    this.sqrt = Math.sqrt;
    this.PI = Math.PI;
    this.TWO_PI = Math.PI * 2;
    this.HALF_PI = Math.PI / 2;

    this.createCanvas = (w, h, renderer) => {
      this.width = w;
      this.height = h;
      if (!this.canvas) {
        this.canvas = document.createElement('canvas');
        if (this._container) this._container.appendChild(this.canvas);
      }
      this.canvas.width = w;
      this.canvas.height = h;
      this.canvas.style.width = w + 'px';
      this.canvas.style.height = h + 'px';
      this.ctx = this.canvas.getContext('2d');
      this.setupTouchEvents();
      return this.canvas;
    };

    this.background = (r, g, b, a) => {
      if (!this.ctx) return;
      this.ctx.save();
      this.ctx.fillStyle = this.resolveColor(r, g, b, a);
      this.ctx.fillRect(0, 0, this.width, this.height);
      this.ctx.restore();
    };

    this.fill = (r, g, b, a) => {
      this._doFill = true;
      this._fill = this.resolveColor(r, g, b, a);
    };

    this.noFill = () => { this._doFill = false; };

    this.stroke = (r, g, b, a) => {
      this._doStroke = true;
      this._stroke = this.resolveColor(r, g, b, a);
    };

    this.noStroke = () => { this._doStroke = false; };
    this.strokeWeight = (w) => { this._strokeWeight = w; };

    this.colorMode = (mode) => { this._colorMode = mode; };
    this.color = (r, g, b, a) => this.resolveColor(r, g, b, a);

    this.ellipse = (x, y, w, h) => {
      if (!this.ctx) return;
      h = h || w;
      this.ctx.beginPath();
      this.ctx.ellipse(x, y, w / 2, h / 2, 0, 0, Math.PI * 2);
      this.drawPath();
    };

    this.circle = (x, y, d) => this.ellipse(x, y, d, d);

    this.rectMode = (m) => { this._rectMode = m; };
    this.ellipseMode = (m) => { /* ellipse is always drawn center + diameter here */ };

    this.rect = (x, y, w, h, r) => {
      if (!this.ctx) return;
      if (this._rectMode === this.CENTER) { x -= w / 2; y -= h / 2; }
      this.ctx.beginPath();
      if (r !== undefined && typeof this.ctx.roundRect === 'function') {
        this.ctx.roundRect(x, y, w, h, r);
      } else {
        this.ctx.rect(x, y, w, h);
      }
      this.drawPath();
    };

    this.line = (x1, y1, x2, y2) => {
      if (!this.ctx) return;
      this.ctx.beginPath();
      this.ctx.moveTo(x1, y1);
      this.ctx.lineTo(x2, y2);
      if (this._doStroke) {
        this.ctx.strokeStyle = this._stroke;
        this.ctx.lineWidth = this._strokeWeight;
        this.ctx.stroke();
      }
    };

    this.point = (x, y) => this.circle(x, y, this._strokeWeight);

    this.push = () => { if (this.ctx) this.ctx.save(); };
    this.pop = () => { if (this.ctx) this.ctx.restore(); };
    this.translate = (x, y) => { if (this.ctx) this.ctx.translate(x, y); };
    this.rotate = (r) => { if (this.ctx) this.ctx.rotate(r); };
    this.scale = (s) => { if (this.ctx) this.ctx.scale(s, s); };

    this.beginShape = () => { if (this.ctx) { this.ctx.beginPath(); this._shapeStarted = true; } };
    this.vertex = (x, y) => {
      if (this.ctx && this._shapeStarted) {
        this.ctx.lineTo(x, y);
      }
    };
    this.endShape = (close) => {
      if (this.ctx && this._shapeStarted) {
        if (close) this.ctx.closePath();
        this.drawPath();
        this._shapeStarted = false;
      }
    };

    this.drawPath = () => {
      if (this._doFill) {
        this.ctx.fillStyle = this._fill;
        this.ctx.fill();
      }
      if (this._doStroke) {
        this.ctx.strokeStyle = this._stroke;
        this.ctx.lineWidth = this._strokeWeight;
        this.ctx.stroke();
      }
    };

    this.noLoop = () => { this.isLooping = false; };
    this.loop = () => {
      if (!this.isLooping) {
        this.isLooping = true;
        this.animate();
      }
    };

    this.remove = () => {
      this.isLooping = false;
      if (this._animFrameId) cancelAnimationFrame(this._animFrameId);
      if (this.canvas && this.canvas.parentNode) {
        this.canvas.parentNode.removeChild(this.canvas);
      }
    };

    this.setupTouchEvents = () => {
      if (!this.canvas) return;
      const updateCoords = (e) => {
        const rect = this.canvas.getBoundingClientRect();
        this.pmouseX = this.mouseX;
        this.pmouseY = this.mouseY;

        if (e.touches && e.touches.length > 0) {
          this.touches = Array.from(e.touches).map(t => ({
            x: t.clientX - rect.left,
            y: t.clientY - rect.top
          }));
          this.mouseX = this.touchX = this.touches[0].x;
          this.mouseY = this.touchY = this.touches[0].y;
        } else {
          this.mouseX = e.clientX - rect.left;
          this.mouseY = e.clientY - rect.top;
        }
      };

      this.canvas.addEventListener('pointerdown', (e) => {
        this.mouseIsPressed = true;
        updateCoords(e);
        if (typeof this.mousePressed === 'function') this.mousePressed();
        if (typeof this.touchStarted === 'function') this.touchStarted();
      });

      this.canvas.addEventListener('pointermove', (e) => {
        updateCoords(e);
        if (this.mouseIsPressed && typeof this.mouseDragged === 'function') this.mouseDragged();
      });

      window.addEventListener('pointerup', () => {
        this.mouseIsPressed = false;
        if (typeof this.mouseReleased === 'function') this.mouseReleased();
        if (typeof this.touchEnded === 'function') this.touchEnded();
      });
    };

    this.animate = () => {
      if (!this.isLooping) return;
      const now = performance.now();
      const dt = now - this._lastFrameTime;
      this._fps = 1000 / (dt || 16);
      this._lastFrameTime = now;

      if (typeof this.draw === 'function') {
        try {
          this.draw();
        } catch (err) {
          console.error('Error in p5 draw loop:', err);
          if (window.AndroidBridge && window.AndroidBridge.onJSError) {
            window.AndroidBridge.onJSError(err.message, 0);
          }
          this.noLoop();
        }
      }
      this.frameCount++;
      this._animFrameId = requestAnimationFrame(this.animate.bind(this));
    };

    // Execute setup and start animation loop
    try {
      sketchFunc(this);
      if (typeof this.setup === 'function') this.setup();
      this.animate();
    } catch (err) {
      console.error('Error in p5 setup:', err);
      if (window.AndroidBridge && window.AndroidBridge.onJSError) {
        window.AndroidBridge.onJSError(err.message, 0);
      }
    }
  }

  global.p5 = p5;
})(window);
